WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY unit_price DESC, id) AS rank_in_group FROM order_items QUALIFY rank_in_group = 1) SELECT product_id, CASE WHEN unit_price >= 410 THEN 'PREMIUM' ELSE 'STANDARD' END AS unit_price_tier, order_id, COUNT(*) AS row_count, STDDEV_SAMP(quantity) AS quantity_stddev FROM ranked GROUP BY GROUPING SETS ((product_id, CASE WHEN unit_price >= 410 THEN 'PREMIUM' ELSE 'STANDARD' END, order_id), (product_id, CASE WHEN unit_price >= 410 THEN 'PREMIUM' ELSE 'STANDARD' END))
